paragraph.math:
$$\begin{array}{l}
  {2t^{3} - \{ t^{2} - \lbrack t - (2t - 1)\rbrack + 4\}} \\
  {\quad = 2t^{3} - \{ t^{2} - \lbrack t - 2t + 1\rbrack + 4\}} \\
  {\quad = 2t^{3} - \{ t^{2} - \lbrack - t + 1\rbrack + 4\}\begin{array}{l}
  {\qquad\text{Remove parentheses and combine}} \\
  {\qquad\text{like terms within brackets.}}
  \end{array}} \\
  {\quad{= 2t^{3} - \{ t^{2} + t - 1 + 4\}}\qquad\text{Remove brackets.}} \\
  {\quad{= 2t^{3} - \{ t^{2} + t + 3\}}\qquad\text{Combine like terms within braces.}} \\
  {\quad{= 2t^{3} - t^{2} - t - 3}\qquad\text{Remove braces.}}
  \end{array}$$

$$\begin{array}{l}
  {4x{(x + 1)}^{1 \slash 2} - 2x^{2}\left( \frac{1}{2} \right){(x + 1)}^{- 1 \slash 2} = 4x{(x + 1)}^{1 \slash 2} - x^{2}{(x + 1)}^{- 1 \slash 2}} \\
  {\quad = x{(x + 1)}^{- 1 \slash 2}\lbrack 4{(x + 1)}^{1 \slash 2}{(x + 1)}^{1 \slash 2} - x\rbrack} \\
  {\quad = x{(x + 1)}^{- 1 \slash 2}\lbrack 4(x + 1) - x\rbrack} \\
  {\quad = x{(x + 1)}^{- 1 \slash 2}(4x + 4 - x) = x{(x + 1)}^{- 1 \slash 2}(3x + 4)}
  \end{array}$$

$$\begin{array}{l}
  {{\frac{1}{x + h} - \frac{1}{x}} = \frac{x - (x + h)}{x(x + h)}\qquad{{LCD} = x(x + h)}} \\
  {\phantom{\frac{1}{x + h} - \frac{1}{x}} = \frac{x - x - h}{x(x + h)}\qquad\text{Remove parentheses.}} \\
  {\phantom{\frac{1}{x + h} - \frac{1}{x}} = \frac{- h}{x(x + h)}\qquad\text{Combine like terms.}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{x^{- 1} + y^{- 1}}{x^{- 2} - y^{- 2}} = {\frac{\frac{1}{x} + \frac{1}{y}}{\frac{1}{x^{2}} - \frac{1}{y^{2}}} = \frac{\frac{y + x}{\mathit{xy}}}{\frac{y^{2} - x^{2}}{x^{2}y^{2}}}}\qquad{x^{- n} = \frac{1}{x^{n}}}} \\
  {\phantom{\frac{x^{- 1} + y^{- 1}}{x^{- 2} - y^{- 2}}} = {\frac{y + x}{\mathit{xy}} \cdot \frac{x^{2}y^{2}}{y^{2} - x^{2}} = \frac{y + x}{\mathit{xy}} \cdot \frac{x^{2}y^{2}}{(y + x)(y - x)}}} \\
  {\phantom{\frac{x^{- 1} + y^{- 1}}{x^{- 2} - y^{- 2}}} = \frac{\mathit{xy}}{y - x}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\sqrt{1 + h} - 1}{h} = {\frac{\sqrt{1 + h} - 1}{h} \cdot \frac{\sqrt{1 + h} + 1}{\sqrt{1 + h} + 1}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{{(\sqrt{1 + h})}^{2} - {(1)}^{2}}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1 + h - 1}{h{({\sqrt{1 + h} + 1})}}\qquad\begin{array}{l}
  {{(\sqrt{1 + h})}^{2} = {\sqrt{1 + h} \cdot \sqrt{1 + h}}} \\
  {\phantom{{(\sqrt{1 + h})}^{2}} = {1 + h}}
  \end{array}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{h}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1}{\sqrt{1 + h} + 1}}
  \end{array}$$
